begin;
create schema if not exists alexmar;
create extension if not exists unaccent with schema extensions;
create extension if not exists pg_trgm with schema extensions;
revoke all on schema alexmar from public, anon, authenticated;

create table alexmar.perfiles(id uuid primary key references auth.users(id),nombre text not null,rol text not null check(rol in ('administrador','ventas','inventario','lectura')),activo boolean not null default true);
create table alexmar.productos(id uuid primary key default gen_random_uuid(),nombre text not null check(length(trim(nombre))>0),descripcion text,categoria text not null default '',compatibilidad text not null default '',marca text not null default '',referencia text not null default '',alias text not null default '',ubicacion text not null default '',activo boolean not null default true,origen text,creado timestamptz not null default now());
create table alexmar.variantes(id uuid primary key default gen_random_uuid(),producto_id uuid not null references alexmar.productos,atributos jsonb not null default '{}',nombre text not null default 'Principal',precio numeric(20,4) check(precio>=0),costo numeric(20,4) check(costo>=0),minimo numeric(20,4) not null default 0 check(minimo>=0),unique(producto_id,nombre));
create table alexmar.compatibilidades(id uuid primary key default gen_random_uuid(),producto_id uuid not null references alexmar.productos,marca text not null,modelo text not null,anio_desde integer,anio_hasta integer,universal boolean not null default false,check(anio_hasta is null or anio_desde is null or anio_hasta>=anio_desde));
create table alexmar.movimientos_stock(id uuid primary key default gen_random_uuid(),variante_id uuid not null references alexmar.variantes,cantidad numeric(20,4) not null,motivo text not null,usuario_id uuid references auth.users,idempotencia text not null unique,creado timestamptz not null default now());
create table alexmar.reservas(id uuid primary key default gen_random_uuid(),variante_id uuid not null references alexmar.variantes,cantidad numeric(20,4) not null check(cantidad>0),estado text not null check(estado in ('activa','consumida','liberada')),referencia text not null);
create table alexmar.clientes(id uuid primary key default gen_random_uuid(),nombre text not null check(length(trim(nombre))>0),documento text,telefono text,direccion text,activo boolean not null default true,origen text);
create table alexmar.movimientos_cuenta(id uuid primary key default gen_random_uuid(),cliente_id uuid not null references alexmar.clientes,tipo text not null check(tipo in ('CARGO','ABONO','TITULO')),fecha timestamptz not null,descripcion text not null,moneda text not null default 'USD' check(moneda in ('USD','VES','COP')),monto numeric(20,4) not null check(monto>=0),activo boolean not null default true,origen text,datos_originales jsonb);
create table alexmar.notas(id uuid primary key default gen_random_uuid(),titulo text not null,contenido text not null,activo boolean not null default true,origen text,creado timestamptz not null default now());
create table alexmar.consultas(id uuid primary key default gen_random_uuid(),usuario_id uuid not null references auth.users,nombre text not null,filtros text not null,unique(usuario_id,nombre));
create table alexmar.lotes(id uuid primary key default gen_random_uuid(),huella text not null unique,resumen jsonb not null,usuario_id uuid not null references auth.users,creado timestamptz not null default now());
create table alexmar.origenes(tipo text not null,origen_id text not null,nuevo_id uuid not null,lote_id uuid not null references alexmar.lotes,datos jsonb not null,primary key(tipo,origen_id));
create table alexmar.auditoria(id bigint generated always as identity primary key,usuario_id uuid,tabla text not null,operacion text not null,registro_id text,anterior jsonb,nuevo jsonb,creado timestamptz not null default now());
create index cuenta_cliente_fecha on alexmar.movimientos_cuenta(cliente_id,fecha,id);
create index stock_variante on alexmar.movimientos_stock(variante_id);
create index reservas_variante on alexmar.reservas(variante_id) where estado='activa';
create index producto_nombre on alexmar.productos(nombre,id);
create index origen_cliente on alexmar.movimientos_cuenta(origen);

create function alexmar.normalizar(t text) returns text language sql immutable set search_path=pg_catalog,extensions as $$ select trim(regexp_replace(lower(extensions.unaccent(coalesce(t,''))),'\s+',' ','g')) $$;
create index producto_busqueda on alexmar.productos using gin ((alexmar.normalizar(nombre||' '||coalesce(descripcion,'')||' '||categoria||' '||compatibilidad||' '||marca||' '||referencia||' '||alias)) extensions.gin_trgm_ops);
create function alexmar.exigir(roles text[] default array['administrador','ventas','inventario','lectura']) returns text language plpgsql security definer set search_path=pg_catalog,alexmar as $$declare r text;begin select rol into r from alexmar.perfiles where id=auth.uid() and activo;if r is null or not(r=any(roles)) then raise exception 'No tienes permiso para esta operación.' using errcode='42501';end if;return r;end $$;
create function public.mi_perfil() returns jsonb language sql stable security definer set search_path=pg_catalog,alexmar as $$select jsonb_build_object('id',id,'nombre',nombre,'rol',rol) from alexmar.perfiles where id=auth.uid() and activo $$;
create function alexmar.auditar() returns trigger language plpgsql security definer set search_path=pg_catalog,alexmar as $$begin insert into alexmar.auditoria(usuario_id,tabla,operacion,registro_id,anterior,nuevo) values(auth.uid(),tg_table_name,tg_op,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'),case when tg_op<>'INSERT' then to_jsonb(old) end,case when tg_op<>'DELETE' then to_jsonb(new) end);return coalesce(new,old);end $$;
do $$declare t text;begin foreach t in array array['perfiles','productos','variantes','compatibilidades','movimientos_stock','reservas','clientes','movimientos_cuenta','notas','consultas','lotes','origenes'] loop execute format('alter table alexmar.%I enable row level security',t);execute format('create trigger auditar after insert or update or delete on alexmar.%I for each row execute function alexmar.auditar()',t);end loop;end $$;
alter table alexmar.auditoria enable row level security;

create function public.buscar_productos(p jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar,extensions as $$
declare r text;resultado jsonb;pag integer:=greatest(1,least(coalesce((p->>'pagina')::int,1),100000));q text:=alexmar.normalizar(p->>'q');begin
r:=alexmar.exigir();
with base as (
 select a.*,v.id variante_id,v.precio,v.costo,v.minimo,
 coalesce((select sum(cantidad) from alexmar.movimientos_stock where variante_id=v.id),0) fisico,
 coalesce((select sum(cantidad) from alexmar.reservas where variante_id=v.id and estado='activa'),0) reservado,
 alexmar.normalizar(a.nombre||' '||coalesce(a.descripcion,'')||' '||a.categoria||' '||a.compatibilidad||' '||a.marca||' '||a.referencia||' '||a.alias||' '||coalesce((select string_agg(c.marca||' '||c.modelo||' '||coalesce(c.anio_desde::text,''),' ') from alexmar.compatibilidades c where c.producto_id=a.id),'')) texto
 from alexmar.productos a join alexmar.variantes v on v.producto_id=a.id and v.nombre='Principal'
), filtrados as (
 select *,fisico-reservado disponible,case when q=alexmar.normalizar(referencia) and q<>'' then 0 when q=alexmar.normalizar(nombre) then 1 when not exists(select 1 from unnest(string_to_array(q,' ')) palabra where strpos(texto,palabra)=0) then 2 else 3 end rango
 from base where
 (coalesce(p->>'estado','activos')='todos' or activo=(coalesce(p->>'estado','activos')='activos'))
 and (coalesce(p->>'categoria','')='' or categoria=p->>'categoria')
 and (coalesce(p->>'marca','')='' or marca=p->>'marca')
 and (coalesce(p->>'precio','')='' or (p->>'precio'='sin' and precio is null) or (p->>'precio'='con' and precio is not null))
 and (coalesce(p->>'ubicacion','')='' or strpos(alexmar.normalizar(ubicacion),alexmar.normalizar(p->>'ubicacion'))>0)
 and (q='' or not exists(select 1 from unnest(string_to_array(q,' ')) palabra where strpos(texto,palabra)=0) or extensions.word_similarity(q,texto)>0.45)
 and (coalesce(p->>'vehiculo','')='' or strpos(alexmar.normalizar(compatibilidad),alexmar.normalizar(p->>'vehiculo'))>0 or exists(select 1 from alexmar.compatibilidades c where c.producto_id=base.id and (c.universal or strpos(alexmar.normalizar(c.marca||' '||c.modelo),alexmar.normalizar(p->>'vehiculo'))>0)))
 and (coalesce(p->>'anio','')='' or exists(select 1 from alexmar.compatibilidades c where c.producto_id=base.id and (c.universal or ((c.anio_desde is null or c.anio_desde<=(p->>'anio')::int) and (c.anio_hasta is null or c.anio_hasta>=(p->>'anio')::int)))))
 and (coalesce(p->>'precio_min','')='' or precio>=(p->>'precio_min')::numeric)
 and (coalesce(p->>'precio_max','')='' or precio<=(p->>'precio_max')::numeric)
), seleccion as (
 select * from filtrados where (coalesce(p->>'stock','')='' or (p->>'stock'='disponible' and disponible>0) or (p->>'stock'='agotado' and disponible<=0) or (p->>'stock'='bajo' and disponible<minimo))
), ordenados as (
 select *,row_number() over(order by
 case when coalesce(p->>'orden','relevancia')='relevancia' then rango end,
 case when p->>'orden'='precio' then precio end nulls last,
 case when p->>'orden'='existencia' then disponible end desc,
 case when coalesce(p->>'orden','relevancia')='relevancia' then extensions.word_similarity(q,texto) end desc,
 nombre,id) posicion from seleccion
), pagina as (select * from ordenados where posicion between (pag-1)*30+1 and pag*30)
select jsonb_build_object('filas',coalesce((select jsonb_agg(jsonb_build_object('id',id,'variante_id',variante_id,'nombre',nombre,'descripcion',descripcion,'categoria',categoria,'compatibilidad',compatibilidad,'marca',marca,'referencia',referencia,'alias',alias,'ubicacion',ubicacion,'activo',activo,'precio',precio::text,'minimo',minimo::text,'fisico',fisico::text,'reservado',reservado::text,'disponible',disponible::text,'aproximado',rango=3)||case when r in ('administrador','inventario') then jsonb_build_object('costo',costo::text) else '{}'::jsonb end order by posicion) from pagina),'[]'::jsonb),'total',(select count(*) from seleccion),'pagina',pag,'paginas',greatest(1,ceil((select count(*) from seleccion)/30.0))) into resultado;return resultado;end $$;
create function public.opciones_catalogo() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$begin perform alexmar.exigir();return jsonb_build_object('categorias',(select coalesce(jsonb_agg(categoria order by categoria),'[]') from (select distinct categoria from alexmar.productos where activo and categoria<>'') t),'marcas',(select coalesce(jsonb_agg(marca order by marca),'[]') from (select distinct marca from alexmar.productos where activo and marca<>'') t),'consultas',(select coalesce(jsonb_agg(jsonb_build_object('nombre',nombre,'filtros',filtros)),'[]') from alexmar.consultas where usuario_id=auth.uid()));end $$;
create function public.ficha_producto(p_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$declare r text;begin r:=alexmar.exigir();return (select jsonb_build_object('id',a.id,'nombre',a.nombre,'descripcion',a.descripcion,'categoria',a.categoria,'compatibilidad',a.compatibilidad,'marca',a.marca,'referencia',a.referencia,'alias',a.alias,'ubicacion',a.ubicacion,'activo',a.activo,'precio',v.precio::text,'minimo',v.minimo::text,'fisico',coalesce((select sum(cantidad) from alexmar.movimientos_stock where variante_id=v.id),0)::text,'reservado',coalesce((select sum(cantidad) from alexmar.reservas where variante_id=v.id and estado='activa'),0)::text)||case when r in ('administrador','inventario') then jsonb_build_object('costo',v.costo::text) else '{}'::jsonb end from alexmar.productos a join alexmar.variantes v on v.producto_id=a.id and v.nombre='Principal' where a.id=p_id);end $$;
create function public.guardar_producto(p jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,alexmar as $$declare i uuid:=coalesce(nullif(p->>'id','')::uuid,gen_random_uuid());begin perform alexmar.exigir(array['administrador','inventario']);insert into alexmar.productos(id,nombre,descripcion,categoria,compatibilidad,marca,referencia,alias,ubicacion,activo) values(i,p->>'nombre',p->>'descripcion',coalesce(p->>'categoria',''),coalesce(p->>'compatibilidad',''),coalesce(p->>'marca',''),coalesce(p->>'referencia',''),coalesce(p->>'alias',''),coalesce(p->>'ubicacion',''),coalesce((p->>'activo')::boolean,true)) on conflict(id) do update set nombre=excluded.nombre,descripcion=excluded.descripcion,categoria=excluded.categoria,compatibilidad=excluded.compatibilidad,marca=excluded.marca,referencia=excluded.referencia,alias=excluded.alias,ubicacion=excluded.ubicacion,activo=excluded.activo;insert into alexmar.variantes(producto_id,precio,costo,minimo) values(i,(p->>'precio')::numeric,(p->>'costo')::numeric,coalesce((p->>'minimo')::numeric,0)) on conflict(producto_id,nombre) do update set precio=excluded.precio,costo=excluded.costo,minimo=excluded.minimo;return i;end $$;
create function public.ajustar_stock(p_id uuid,p_contado numeric,p_motivo text,p_clave text) returns void language plpgsql security definer set search_path=pg_catalog,alexmar as $$declare v uuid;s numeric;begin perform alexmar.exigir(array['administrador','inventario']);if p_contado<0 or p_contado is null or p_contado<>round(p_contado,4) or length(trim(p_motivo))<5 or length(p_clave)<10 then raise exception 'Indica cantidad no negativa y un motivo de al menos cinco caracteres.';end if;select id into strict v from alexmar.variantes where producto_id=p_id and nombre='Principal' for update;if exists(select 1 from alexmar.movimientos_stock where idempotencia=p_clave) then return;end if;select coalesce(sum(cantidad),0) into s from alexmar.movimientos_stock where variante_id=v;insert into alexmar.movimientos_stock(variante_id,cantidad,motivo,usuario_id,idempotencia) values(v,p_contado-s,p_motivo,auth.uid(),p_clave);end $$;
create function public.kardex(p_id uuid,p_pagina integer default 1) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$declare n integer:=greatest(1,p_pagina);begin perform alexmar.exigir();return (with t as(select m.id,m.cantidad::text,m.motivo,m.creado,sum(m.cantidad) over(order by m.creado,m.id)::text saldo from alexmar.movimientos_stock m join alexmar.variantes v on v.id=m.variante_id where v.producto_id=p_id),pg as(select * from t order by creado desc,id desc limit 30 offset (n-1)*30) select jsonb_build_object('filas',coalesce((select jsonb_agg(to_jsonb(pg)) from pg),'[]'),'total',(select count(*) from t),'pagina',n,'paginas',greatest(1,ceil((select count(*) from t)/30.0))));end $$;
create function public.guardar_consulta(p_nombre text,p_filtros text) returns void language plpgsql security definer set search_path=pg_catalog,alexmar as $$begin perform alexmar.exigir();if length(trim(p_nombre))=0 or length(p_nombre)>80 or length(p_filtros)>2000 then raise exception 'Nombre o consulta no válidos.';end if;insert into alexmar.consultas(usuario_id,nombre,filtros) values(auth.uid(),p_nombre,p_filtros) on conflict(usuario_id,nombre) do update set filtros=excluded.filtros;end $$;
create function public.buscar_clientes(p jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$declare n integer:=greatest(1,coalesce((p->>'pagina')::int,1));begin perform alexmar.exigir(array['administrador','ventas']);return (with t as(select c.*,coalesce((select sum(case when tipo='CARGO' then monto when tipo='ABONO' then -monto else 0 end) from alexmar.movimientos_cuenta where cliente_id=c.id and activo and moneda='USD'),0)::text saldo from alexmar.clientes c where c.activo and (coalesce(p->>'q','')='' or strpos(alexmar.normalizar(c.nombre||' '||coalesce(c.documento,'')||' '||coalesce(c.telefono,'')),alexmar.normalizar(p->>'q'))>0)),pg as(select * from t order by nombre,id limit 30 offset (n-1)*30) select jsonb_build_object('filas',coalesce((select jsonb_agg(to_jsonb(pg)) from pg),'[]'),'total',(select count(*) from t),'pagina',n,'paginas',greatest(1,ceil((select count(*) from t)/30.0))));end $$;
create function public.guardar_cliente(p jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,alexmar as $$declare i uuid:=coalesce(nullif(p->>'id','')::uuid,gen_random_uuid());begin perform alexmar.exigir(array['administrador','ventas']);insert into alexmar.clientes(id,nombre,documento,telefono,direccion) values(i,p->>'nombre',p->>'documento',p->>'telefono',p->>'direccion') on conflict(id) do update set nombre=excluded.nombre,documento=excluded.documento,telefono=excluded.telefono,direccion=excluded.direccion;return i;end $$;
create function public.estado_cliente(p_id uuid,p_desde date default null,p_hasta date default null,p_pagina integer default 1,p_moneda text default 'USD') returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$declare r jsonb;n integer:=greatest(1,p_pagina);begin perform alexmar.exigir(array['administrador','ventas']);if p_desde>p_hasta then raise exception 'El inicio debe ser anterior al final.';end if;
with t as(select id,fecha,descripcion,tipo,monto::text importe,case when tipo='CARGO' then monto when tipo='ABONO' then -monto else 0 end firmado from alexmar.movimientos_cuenta where cliente_id=p_id and activo and moneda=p_moneda),acumulados as(select *,sum(firmado) over(order by fecha,id)::text saldo from t),filtrados as(select * from acumulados where (p_desde is null or (fecha at time zone 'America/Caracas')::date>=p_desde) and (p_hasta is null or (fecha at time zone 'America/Caracas')::date<=p_hasta)),pg as(select * from filtrados order by fecha,id limit 30 offset (n-1)*30)
select jsonb_build_object('cliente',(select to_jsonb(c) from alexmar.clientes c where id=p_id),'moneda',p_moneda,'anterior',coalesce((select sum(firmado) from t where p_desde is not null and (fecha at time zone 'America/Caracas')::date<p_desde),0)::text,'final',coalesce((select sum(firmado) from t where p_hasta is null or (fecha at time zone 'America/Caracas')::date<=p_hasta),0)::text,'cargos',coalesce((select sum(firmado) from filtrados where tipo='CARGO'),0)::text,'abonos',coalesce((select -sum(firmado) from filtrados where tipo='ABONO'),0)::text,'filas',coalesce((select jsonb_agg(to_jsonb(pg)) from pg),'[]'),'total',(select count(*) from filtrados),'pagina',n,'paginas',greatest(1,ceil((select count(*) from filtrados)/30.0))) into r;return r;end $$;
create function public.listar_notas(p_pagina integer default 1) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$declare n integer:=greatest(1,p_pagina);begin perform alexmar.exigir(array['administrador']);return (with t as(select id,titulo,contenido,creado from alexmar.notas where activo),pg as(select * from t order by creado desc,id limit 30 offset (n-1)*30) select jsonb_build_object('filas',coalesce((select jsonb_agg(to_jsonb(pg)) from pg),'[]'),'total',(select count(*) from t),'pagina',n,'paginas',greatest(1,ceil((select count(*) from t)/30.0))));end $$;
create function public.guardar_nota(p jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,alexmar as $$declare i uuid:=coalesce(nullif(p->>'id','')::uuid,gen_random_uuid());begin perform alexmar.exigir(array['administrador']);insert into alexmar.notas(id,titulo,contenido) values(i,coalesce(p->>'titulo',''),coalesce(p->>'contenido','')) on conflict(id) do update set titulo=excluded.titulo,contenido=excluded.contenido;return i;end $$;
create function public.listar_perfiles() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$begin perform alexmar.exigir(array['administrador']);return (select coalesce(jsonb_agg(to_jsonb(p) order by nombre,id),'[]') from alexmar.perfiles p);end $$;
create function public.asignar_perfil(p_id uuid,p_nombre text,p_rol text,p_activo boolean) returns void language plpgsql security definer set search_path=pg_catalog,alexmar as $$begin perform alexmar.exigir(array['administrador']);if p_id=auth.uid() and (p_rol<>'administrador' or not p_activo) then raise exception 'No puedes quitar tu propio acceso de administrador.';end if;insert into alexmar.perfiles(id,nombre,rol,activo) values(p_id,p_nombre,p_rol,p_activo) on conflict(id) do update set nombre=excluded.nombre,rol=excluded.rol,activo=excluded.activo;end $$;
create function public.resumen() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,alexmar as $$declare r text;begin r:=alexmar.exigir();return jsonb_build_object('productos',(select count(*) from alexmar.productos where activo),'sin_precio',(select count(*) from alexmar.variantes v join alexmar.productos p on p.id=v.producto_id where p.activo and v.precio is null))||case when r in ('administrador','ventas') then jsonb_build_object('clientes',(select count(*) from alexmar.clientes where activo),'deuda_usd',(select coalesce(sum(case when tipo='CARGO' then monto when tipo='ABONO' then -monto else 0 end),0)::text from alexmar.movimientos_cuenta m join alexmar.clientes c on c.id=m.cliente_id where m.activo and c.activo and m.moneda='USD')) else '{}'::jsonb end;end $$;
-- Solo se acepta una carga inicial sobre una instalación vacía. El histórico se conserva
-- completo en origenes; los movimientos eliminados no afectan los saldos.
create function public.importar_inicial(p jsonb,p_huella text) returns jsonb language plpgsql security definer set search_path=pg_catalog,alexmar as $$
declare lote uuid;r jsonb;v uuid;res jsonb;begin
perform alexmar.exigir(array['administrador']);perform pg_advisory_xact_lock(7061511);
select resumen into res from alexmar.lotes where huella=p_huella;if found then return res||jsonb_build_object('repetido',true);end if;
if exists(select 1 from alexmar.productos) or exists(select 1 from alexmar.clientes) or exists(select 1 from alexmar.notas) then raise exception 'La importación inicial requiere un destino vacío. No se sobrescribe información existente.';end if;
if length(p_huella)<>64 then raise exception 'Huella inválida.';end if;
-- Validación independiente del navegador y de la API.
if exists(select 1 from jsonb_array_elements(p->'detalle_cuentas') m where m->>'tipo_linea' not in ('CARGO','ABONO','TITULO') or (m->>'total_linea')::numeric<0 or (m->>'total_linea')::numeric<>round((m->>'total_linea')::numeric,4)) then raise exception 'Revisa tipos, importes negativos y precisión de los movimientos.';end if;
if exists(select 1 from jsonb_array_elements(p->'clientes') c where c->>'eliminado'='false' and abs((c->>'total_adeudado')::numeric-coalesce((select sum(case m->>'tipo_linea' when 'CARGO' then (m->>'total_linea')::numeric when 'ABONO' then -(m->>'total_linea')::numeric else 0 end) from jsonb_array_elements(p->'detalle_cuentas') m where m->>'id_cliente'=c->>'id' and m->>'eliminado'='false'),0))>0.0001) then raise exception 'Hay diferencias de saldo sin resolver. Importación bloqueada.';end if;
if exists(select 1 from jsonb_array_elements(p->'inventario') a cross join unnest(array['costo','pvp','stock_actual','stock_minimo']) campo where nullif(nullif(a->>campo,''),'null') is not null and ((a->>campo)::numeric<>round((a->>campo)::numeric,4) or (a->>campo)::numeric<0)) then raise exception 'Revisa precisión y valores negativos en inventario.';end if;
res:=jsonb_build_object('inventario',jsonb_array_length(p->'inventario'),'clientes',jsonb_array_length(p->'clientes'),'detalle_cuentas',jsonb_array_length(p->'detalle_cuentas'),'notas',jsonb_array_length(p->'notas'),'moneda','USD');
insert into alexmar.lotes(huella,resumen,usuario_id) values(p_huella,res,auth.uid()) returning id into lote;
for r in select value from jsonb_array_elements(p->'inventario') loop
 insert into alexmar.productos(id,nombre,descripcion,categoria,compatibilidad,activo,origen) values((r->>'id')::uuid,r->>'nombre_producto',r->>'descripcion',coalesce(r->>'categoria_tags',''),coalesce(r->>'compatibilidad_vehiculos',''),not (r->>'eliminado')::boolean,'supabase_anterior');
 insert into alexmar.variantes(producto_id,precio,costo,minimo) values((r->>'id')::uuid,nullif(nullif(r->>'pvp',''),'null')::numeric,nullif(nullif(r->>'costo',''),'null')::numeric,(r->>'stock_minimo')::numeric) returning id into v;
 insert into alexmar.movimientos_stock(variante_id,cantidad,motivo,usuario_id,idempotencia) values(v,(r->>'stock_actual')::numeric,'Existencia inicial migrada; historial anterior no descuenta stock',auth.uid(),'migracion:'||(r->>'id'));
 insert into alexmar.origenes values('inventario',r->>'id',(r->>'id')::uuid,lote,r);
end loop;
for r in select value from jsonb_array_elements(p->'clientes') loop
 insert into alexmar.clientes(id,nombre,documento,telefono,direccion,activo,origen) values((r->>'id')::uuid,r->>'nombre_cliente',r->>'cedula',r->>'telefono',r->>'direccion',not (r->>'eliminado')::boolean,'supabase_anterior');
 insert into alexmar.origenes values('clientes',r->>'id',(r->>'id')::uuid,lote,r);
end loop;
for r in select value from jsonb_array_elements(p->'detalle_cuentas') loop
 insert into alexmar.movimientos_cuenta(id,cliente_id,tipo,fecha,descripcion,moneda,monto,activo,origen,datos_originales) values((r->>'id')::uuid,(r->>'id_cliente')::uuid,r->>'tipo_linea',(r->>'fecha')::timestamptz,coalesce(r->>'descripcion',''),'USD',(r->>'total_linea')::numeric,not (r->>'eliminado')::boolean,'supabase_anterior',r);
 insert into alexmar.origenes values('detalle_cuentas',r->>'id',(r->>'id')::uuid,lote,r);
end loop;
for r in select value from jsonb_array_elements(p->'notas') loop
 insert into alexmar.notas(id,titulo,contenido,activo,origen) values((r->>'id')::uuid,coalesce(r->>'titulo',''),coalesce(r->>'contenido',''),not (r->>'eliminado')::boolean,'supabase_anterior');
 insert into alexmar.origenes values('notas',r->>'id',(r->>'id')::uuid,lote,r);
end loop;
return res||jsonb_build_object('lote',lote);end $$;

-- Defensa adicional: ninguna tabla de negocio puede consultarse directamente por API.
revoke all on all tables in schema alexmar from public,anon,authenticated;
revoke all on all functions in schema alexmar from public,anon,authenticated;
-- Aplicar permisos únicamente a las funciones de esta entrega.
do $$declare f record;begin for f in select p.oid::regprocedure nombre from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['mi_perfil','buscar_productos','opciones_catalogo','ficha_producto','guardar_producto','ajustar_stock','kardex','guardar_consulta','buscar_clientes','guardar_cliente','estado_cliente','listar_notas','guardar_nota','listar_perfiles','asignar_perfil','resumen','importar_inicial']) loop execute format('revoke all on function %s from public,anon',f.nombre);execute format('grant execute on function %s to authenticated',f.nombre);end loop;end $$;
commit;
